// Get all incoming items
const items = $input.all();

// Extract query from the first item, or use an empty object
const q = (items[0] && items[0].json && items[0].json.query) ? items[0].json.query : {};

// Safely parse and default parameters
// CHANGED: Use 'search' instead of 'name' to match frontend
const search = q.search || q.name || "";
const limit = Number.isInteger(parseInt(q.itemsPerPage || q.pageSize)) ? parseInt(q.itemsPerPage || q.pageSize) : 10;
const pageNo = Number.isInteger(parseInt(q.page || q.pageNo)) ? parseInt(q.page || q.pageNo) : 1;
const offset = (pageNo - 1) * limit;

// Return a single item with params for the next node
return [
  {
    json: {
      params: {
        search,
        limit,
        offset
      }
    }
  }
];

const keysToRemove = ['image_content', 'image_type'];

return $input.all().map(item => {
  const json = {...item.json};
  keysToRemove.forEach(k => delete json[k]);

  // Optionally recalculate or add the filename from existing properties
  json.filename = `http://192.168.0.7:5678/webhook/image?filename=component_${item.json.id}.${item.json.image_type || 'jpeg'}`;

  return { json };
});

return $input.all().map(item => {
  const data = item.json;
  const imageBuffer = Buffer.from(data.image_content.data);
  const imageType = data.image_type || 'jpeg';
  const base64Image = imageBuffer.toString('base64');

  // Generate filename
  const filename = `component_${data.id}.${imageType}`;

  return {
    json:  {  // 'data' is the standard expected binary property name
        data: base64Image,
        mimeType: `image/${imageType}`,
        fileName: filename
      }
  };
});

const item = $input.first().json;
if (!item) {
  return [{ json: { success: false, message: 'Component not found', data: null } }];
}
return [{ json: { success: true, message: 'Component found', data: item } }];

const keysToRemove = ['image_content', 'image_type'];

return $input.all().map(item => {
  const json = {...item.json};
  keysToRemove.forEach(k => delete json[k]);

  // Optionally recalculate or add the filename from existing properties
  json.filename = `http://192.168.0.7:5678/webhook/image?filename=component_${item.json.id}.${item.json.image_type || 'jpeg'}`;

  return { json };
});

const keysToRemove = ['image_content', 'image_type'];

return $input.all().map(item => {
  const json = {...item.json};
  keysToRemove.forEach(k => delete json[k]);

  // Optionally recalculate or add the filename from existing properties
  json.filename = `http://192.168.0.7:5678/webhook/image?filename=component_${item.json.id}.${item.json.image_type || 'jpeg'}`;

  return { json };
});

// Collect all items into an array
const items = [];
for (const item of $input.all()) {
  items.push(item.json);
}

// Wrap the array in an object with a 'data' property
return { items  };

const componentId = $json.body.component_id;
const updates = [];

// Only add fields that are actually present in the request
if ($json.body.name !== undefined && $json.body.name !== null) {
  const sanitized = String($json.body.name).replace(/'/g, "''");
  updates.push(`name = '${sanitized}'`);
}

if ($json.body.category_id !== undefined && $json.body.category_id !== null) {
  updates.push(`category_id = ${$json.body.category_id}`);
}

if ($json.body.box_id !== undefined && $json.body.box_id !== null) {
  updates.push(`box_id = ${$json.body.box_id}`);
}

if ($json.body.description !== undefined && $json.body.description !== null) {
  const sanitized = String($json.body.description).replace(/'/g, "''");
  updates.push(`description = '${sanitized}'`);
}

// Handle image update - only if all three are present
if ($json.body.image_content && $json.body.image_type && $json.body.imaeg_name) {
  updates.push(`image_content = decode('${$json.body.image_content}', 'base64')`);
  updates.push(`image_type = '${$json.body.image_type}'`);
  const sanitizedName = String($json.body.imaeg_name).replace(/'/g, "''");
  updates.push(`imaeg_name = '${sanitizedName}'`);
}

// Check if there are any updates
if (updates.length === 0) {
  throw new Error('No fields to update');
}

// Build SQL - FIXED: Construct proper data URL with image/ prefix
const sql = `UPDATE components 
SET ${updates.join(', ')}
WHERE component_id = ${componentId}
RETURNING 
  component_id, 
  name, 
  category_id, 
  box_id, 
  description, 
  date_added,
  'data:image/' || image_type || ';base64,' || encode(image_content, 'base64') as filename,
  image_type, 
  imaeg_name`;

return { json: { sql } };

const result = $input.all()[0].json;

console.log('Database result:', result);

// Return the updated component
return {
  json: result[0] || result
};

// Extract data from request body
const body = $json.body;

// Validate required fields
if (!body.name || !body.category_id) {
  throw new Error('Required fields missing: name and category_id are mandatory');
}

// Sanitize string values to prevent SQL injection
const sanitizeName = String(body.name).replace(/'/g, "''");
const sanitizeDescription = body.description ? String(body.description).replace(/'/g, "''") : '';

// Build INSERT query with RETURNING clause
let sql = `INSERT INTO components (
  name,
  category_id,
  box_id,
  description`;

// Add image columns if image data is provided
if (body.image_content && body.image_type && body.imaeg_name) {
  sql += `,
  image_content,
  image_type,
  imaeg_name`;
}

sql += `
) VALUES (
  '${sanitizeName}',
  ${body.category_id},
  ${body.box_id || 'NULL'},
  '${sanitizeDescription}'`;

// Add image values if provided
if (body.image_content && body.image_type && body.imaeg_name) {
  const sanitizeImageName = String(body.imaeg_name).replace(/'/g, "''");
  sql += `,
  decode('${body.image_content}', 'base64'),
  '${body.image_type}',
  '${sanitizeImageName}'`;
}

sql += `
)
RETURNING 
  component_id,
  name,
  category_id,
  box_id,
  description,
  date_added,
  CASE 
    WHEN image_content IS NOT NULL THEN 'data:image/' || image_type || ';base64,' || encode(image_content, 'base64')
    ELSE NULL
  END as filename,
  image_type,
  imaeg_name`;

return { json: { sql } };

const result = $input.all()[0].json;

console.log('Database create result:', result);

// Return the newly created component
return {
  json: result[0] || result
};
